\usetikzlibrary{angles, quotes}
\draw[-{Stealth}] (-1.3,0) -- (1.3,0) node[right] {$x$};
\draw[-{Stealth}] (0,-1.3) -- (0,1.3) node[above] {$y$};
\draw (0,0) circle (1);
\coordinate (O) at (0,0);
\coordinate (P) at (0.8,0.6);
\coordinate (Q) at (0.8,-0.6);
\coordinate (A) at (1,0);
\draw[thick] (O) -- (P);
\draw[thick] (O) -- (Q);
\draw[dashed] (P) -- (Q);
\fill (P) circle (1.2pt) node[above right] {$P(x,y)$};
\fill (Q) circle (1.2pt) node[below right] {$P'(x,-y)$};
\pic[draw, "$\theta$", angle radius=0.5cm, angle eccentricity=1.8] {angle = A--O--P};
